import type { GoModel, ModelField } from '../shared/api-types';

// Matches gofmt'd output of gormcsv's models.tmpl only; not a general Go parser.
const FACTORY_ENTRY = /^\s*"([^"]+)":\s*func\(\) any \{ return &(\w+)\{\} \},$/gm;
const STRUCT_BLOCK = /^type (\w+) struct \{\n([\s\S]*?)^\}/gm;
const FIELD_LINE = /^\s+(\w+)\s+(\S+)(?:\s+`([^`]*)`)?\s*$/;

/** Extracts models and their inferred fields from a models.go generated by `gormcsv inspectcsv`. */
export function parseGeneratedModels(source: string): GoModel[] {
  const keys = new Map<string, string>();
  for (const [, key, name] of source.matchAll(FACTORY_ENTRY)) {
    keys.set(name, key);
  }

  const models: GoModel[] = [];
  for (const [, name, body] of source.matchAll(STRUCT_BLOCK)) {
    const fields: ModelField[] = [];
    for (const line of body.split('\n')) {
      const match = FIELD_LINE.exec(line);
      if (match) {
        const [, fieldName, type, tag] = match;
        fields.push(tag ? { name: fieldName, type, tag } : { name: fieldName, type });
      }
    }
    models.push({ name, key: keys.get(name) ?? name.toLowerCase(), fields });
  }
  return models;
}
